def review(gid,description,contexts):
    if gid in P0_PLANS:
        return dict(P0_PLANS[gid],status='reviewed_before_render',source_description=description,
            source_scripts=[c['script'] for c in contexts],scope='P0 target-first single shot')
    import cafe_first_visit
    if gid in cafe_first_visit.IDS:PLANS[gid]=cafe_first_visit.review(gid)
    import cinematic_resources
    if gid in cinematic_resources.IDS:PLANS[gid]=cinematic_resources.review(gid)
    import cinematic_locations
    if gid in cinematic_locations.IDS:PLANS[gid]=cinematic_locations.review(gid)
    import cinematic_drinks
    if gid in cinematic_drinks.IDS and gid not in cafe_first_visit.IDS:PLANS[gid]=cinematic_drinks.review(gid)
    import entrance_inside
    if gid in entrance_inside.IDS:PLANS[gid]=entrance_inside.review(gid)
    if gid=='bar_low_truckr_mm':
        from bar_transition import REVIEW
        PLANS[gid]=REVIEW
    if gid in ['bag_handoff_low_hold','topdown_unwrap_top_in_cd']:
        from order_handoff import REVIEW
        PLANS[gid]=REVIEW
    if gid not in PLANS:
        import environment_scenes
        if gid in environment_scenes.REGISTRY:PLANS[gid]=environment_scenes.explicit_review(gid,description,contexts)
    if gid not in PLANS:
        import food_scenes
        if gid in food_scenes.REGISTRY:PLANS[gid]=food_scenes.explicit_review(gid,description,contexts)
    if gid not in PLANS:
        import people_scenes
        if gid in people_scenes.REGISTRY:PLANS[gid]=people_scenes.explicit_review(gid,description,contexts)
    assert gid in PLANS,"Scene needs an explicit script/composition review before rendering: "+gid
    plan=dict(PLANS[gid]);plan.update(status="reviewed_before_render",source_description=description,
                                     source_scripts=[c["script"] for c in contexts],
                                     scope="Shot and actual source handover" if gid in ['cup_eye_hold_whipout', 'cup_high_out_dm', 'cup_pour_eye_hold', 'cup_shot_eye_in_cd_through', 'glass_build_eye_hold', 'glass_drink_high_hold', 'glass_eye_tiltd_cc', 'glass_favorite_eye_in_cd', 'glass_flight_high_truckr_cc', 'glass_outro_high_out_dm', 'glass_pour_eye_in_cd_through', 'glass_pour_low_in_cd', 'glasses_clink_center', 'tap_pour_glass', 'tap_taps_low_tiltd_mm'] else "Base shot first; source handover is tracked, not silently omitted",
                                     reviewer_note="Composition choices are practical design judgments; they do not guarantee real-world footage quality")
    for required in ["subject","angle","motion","focal_point","composition","golden_ratio","lighting","contacts","handover"]:
        assert plan.get(required),required
    return plan
